import React, { useState, useEffect } from 'react'
import { supabase } from './supabase.js'
import { useScrollLock } from './lockScroll.js'

const headshot = id => `https://sleepercdn.com/content/nfl/players/${id}.jpg`
const teamLogo = t => t ? `https://sleepercdn.com/images/team_logos/nfl/${t.toLowerCase()}.png` : null

const n = v => (v === null || v === undefined || v === '') ? '—' : v

/* ---------- the whole career, season by season ----------
   Ten years of real stat lines live in player_seasons (2016-2025).
   This is the table no mainstream app gives you — the one that lets
   you see 2019 vs 2020 vs now and form your own opinion. */
const CAREER_COLS = {
  QB: [['pass_yd', 'PASS YD'], ['pass_td', 'PASS TD'], ['pass_int', 'INT'], ['pass_rtg', 'RTG'],
       ['cmp_pct', 'CMP%'], ['rush_yd', 'RUSH YD'], ['rush_td', 'RUSH TD'],
       ['nv_snap_pct', 'SNAP%'], ['nv_cpoe', 'CPOE'], ['nv_ttt', 'TIME TO THROW'],
       ['nv_agg', 'AGGR%'], ['nv_pass_ay', 'AIR YD'], ['nv_pressured', 'PRESSURED'],
       ['nv_blitzed', 'BLITZED'], ['nv_sacked', 'SACKED'], ['nv_bad_throws', 'BAD THROWS'],
       ['nv_pass_epa', 'PASS EPA']],
  RB: [['rush_yd', 'RUSH YD'], ['rush_att', 'CAR'], ['rush_ypa', 'YPC'], ['rush_td', 'RUSH TD'],
       ['rec', 'REC'], ['rec_yd', 'REC YD'], ['rec_td', 'REC TD'], ['touch', 'TOUCH'],
       ['nv_snap_pct', 'SNAP%'], ['nv_ybc', 'YDS B/CONTACT'], ['nv_yac_rush', 'YDS A/CONTACT'],
       ['nv_broken_tkl', 'BRK TKL'], ['nv_ryoe_att', 'RYOE/ATT'], ['nv_box8', '8+ BOX%'],
       ['nv_tgt_share', 'TGT%'], ['nv_rush_epa', 'RUSH EPA']],
  WR: [['rec', 'REC'], ['rec_tgt', 'TGT'], ['rec_yd', 'REC YD'], ['rec_ypr', 'Y/R'],
       ['rec_td', 'REC TD'], ['nv_snap_pct', 'SNAP%'], ['nv_tgt_share', 'TGT%'],
       ['nv_air_yd', 'AIR YD'], ['nv_ay_share', 'AIR YD%'], ['nv_wopr', 'WOPR'],
       ['nv_racr', 'RACR'], ['nv_separation', 'SEPARATION'], ['nv_cushion', 'CUSHION'],
       ['nv_yac_over', 'YAC vs EXP'], ['nv_rec_yac', 'YAC'], ['nv_drops', 'DROPS'],
       ['nv_rec_broken_tkl', 'BRK TKL'], ['nv_rec_epa', 'REC EPA']],
  K: [], DEF: [],
}
CAREER_COLS.TE = CAREER_COLS.WR

function Career({ p, projKey }) {
  const [rows, setRows] = useState(null)
  useEffect(() => {
    let live = true
    supabase.from('player_seasons')
      .select('season,team,stats')
      .eq('player_id', p.id)
      .order('season', { ascending: false })
      .then(({ data, error }) => { if (live) setRows(error ? [] : (data || [])) })
    return () => { live = false }
  }, [p.id])

  const cols = CAREER_COLS[p.pos] || []
  const ptsKey = projKey === 'ppr' ? 'pts_ppr' : projKey === 'half' ? 'pts_half_ppr' : 'pts_std'

  if (rows === null) return <div className="hint pad">Loading career…</div>
  if (!rows.length || !cols.length) return null

  /* A season the player missed still gets a row of zeros with the reason,
     rather than silently vanishing — a gap in the years reads as a bug. */
  const anyDnp = rows.some(r => (r.stats || {}).dnp)

  return (
    <>
      <div className="pc-h">Career — season by season</div>
      <div className="careerwrap">
        <table className="career">
          <thead>
            <tr>
              <th className="cseason">YEAR</th><th>TEAM</th><th>GP</th>
              {cols.map(([k, lab]) => <th key={k}>{lab}</th>)}
              <th>FPTS</th><th>PPG</th><th>RNK</th>
            </tr>
          </thead>
          <tbody>
            {rows.map(r => {
              const st = r.stats || {}
              const out = !!st.dnp
              const rank = st.pos_rank_ppr
              const z = v => out ? 0 : n(v)          // missed season = zeros, not dashes
              return (
                <React.Fragment key={r.season}>
                  <tr className={out ? 'cdnp' : ''}>
                    <td className="cseason"><b>{r.season}</b></td>
                    <td>{r.team || '—'}</td>
                    <td>{z(st.gp)}</td>
                    {cols.map(([k]) => <td key={k}>{z(st[k])}</td>)}
                    <td className="cfp">{z(st[ptsKey])}</td>
                    <td>{z(st.ppg)}</td>
                    <td className={!out && rank != null && rank <= 12 ? 'ctop' : ''}>
                      {out ? '—' : (rank != null ? p.pos + rank : '—')}
                    </td>
                  </tr>
                  {out && (
                    <tr className="cdnprow">
                      <td colSpan={cols.length + 6}>
                        <span className="cdnptag">DID NOT PLAY</span>
                        {st.dnp_label || 'Not on an active roster'}
                        {st.dnp_weeks ? ` · ${st.dnp_weeks} weeks` : ''}
                      </td>
                    </tr>
                  )}
                </React.Fragment>
              )
            })}
          </tbody>
        </table>
      </div>
      <p className="pc-source">
        Season totals from Sleeper's official feed; advanced metrics from nflverse
        (Pro Football Reference + Next Gen Stats).
        {anyDnp && ' A missed season shows as zeros, with the roster status that explains it.'}
      </p>
    </>
  )
}

/* ---------- the advanced block ----------
   The numbers the analytics accounts post and no mainstream fantasy app
   shows. Most recent season the player actually played. Only cells with
   real data render — an empty cell is never filled with a guess. */
const ADV = {
  QB: [['nv_cpoe', 'CPOE', '%'], ['nv_ttt', 'TIME TO THROW', 's'], ['nv_agg', 'AGGRESSIVE', '%'],
       ['nv_pass_ay', 'AIR YARDS', ''], ['nv_pressured', 'PRESSURED', ''], ['nv_blitzed', 'BLITZED', ''],
       ['nv_qb_hit', 'QB HITS', ''], ['nv_sacked', 'SACKED', ''], ['nv_bad_throws', 'BAD THROWS', ''],
       ['nv_pass_epa', 'PASS EPA', ''], ['nv_snap_pct', 'SNAP SHARE', '%']],
  RB: [['nv_ybc', 'YDS BEFORE CONTACT', ''], ['nv_yac_rush', 'YDS AFTER CONTACT', ''],
       ['nv_broken_tkl', 'BROKEN TACKLES', ''], ['nv_ryoe_att', 'RUSH YD OVER EXP/ATT', ''],
       ['nv_eff', 'EFFICIENCY', ''], ['nv_box8', 'VS 8+ IN BOX', '%'],
       ['nv_tgt_share', 'TARGET SHARE', '%'], ['nv_rush_epa', 'RUSH EPA', ''],
       ['nv_rush_fd', 'RUSH 1ST DOWNS', ''], ['nv_snap_pct', 'SNAP SHARE', '%']],
  WR: [['nv_tgt_share', 'TARGET SHARE', '%'], ['nv_air_yd', 'AIR YARDS', ''],
       ['nv_ay_share', 'AIR YARDS SHARE', '%'], ['nv_wopr', 'WOPR', ''], ['nv_racr', 'RACR', ''],
       ['nv_separation', 'SEPARATION', 'yd'], ['nv_cushion', 'CUSHION', 'yd'],
       ['nv_yac_over', 'YAC OVER EXPECTED', ''], ['nv_rec_yac', 'YAC', ''],
       ['nv_drops', 'DROPS', ''], ['nv_rec_broken_tkl', 'BROKEN TACKLES', ''],
       ['nv_rec_fd', 'REC 1ST DOWNS', ''], ['nv_rec_epa', 'REC EPA', ''],
       ['nv_snap_pct', 'SNAP SHARE', '%']],
  K: [], DEF: [],
}
ADV.TE = ADV.WR

function Advanced({ p }) {
  const [row, setRow] = useState(undefined)
  useEffect(() => {
    let live = true
    supabase.from('player_seasons').select('season,stats')
      .eq('player_id', p.id).order('season', { ascending: false }).limit(6)
      .then(({ data }) => {
        if (!live) return
        const played = (data || []).find(r => !(r.stats || {}).dnp)
        setRow(played || null)
      })
    return () => { live = false }
  }, [p.id])

  if (row === undefined) return null
  const cells = (ADV[p.pos] || []).filter(([k]) => row && row.stats[k] != null)
  if (!cells.length) return null

  return (
    <>
      <div className="pc-h">Advanced — {row.season}</div>
      <div className="advgrid">
        {cells.map(([k, lab, unit]) => (
          <div key={k}><s>{lab}</s><b>{row.stats[k]}{unit}</b></div>
        ))}
      </div>
    </>
  )
}

/* Which stat rows matter for which position. Only rows with real data render. */
const SEASON_ROWS = {
  QB: [['pass_cmp', 'CMP'], ['pass_att', 'ATT'], ['pass_yd', 'PASS YDS'], ['pass_td', 'PASS TD'],
       ['pass_int', 'INT'], ['rush_att', 'CAR'], ['rush_yd', 'RUSH YDS'], ['rush_td', 'RUSH TD']],
  RB: [['rush_att', 'CAR'], ['rush_yd', 'RUSH YDS'], ['ypc', 'YPC'], ['rush_td', 'RUSH TD'],
       ['rec', 'REC'], ['rec_yd', 'REC YDS'], ['rec_td', 'REC TD'], ['touch', 'TOUCHES']],
  WR: [['rec', 'REC'], ['rec_tgt', 'TGT'], ['rec_yd', 'REC YDS'], ['ypr', 'YPR'],
       ['rec_td', 'REC TD'], ['rush_att', 'CAR'], ['rush_yd', 'RUSH YDS']],
  TE: [['rec', 'REC'], ['rec_tgt', 'TGT'], ['rec_yd', 'REC YDS'], ['ypr', 'YPR'], ['rec_td', 'REC TD']],
  K:  [], DEF: [],
}

/* Usage + efficiency — the stuff casual apps hide. Last season only. */
const USAGE = [
  ['snap_pct', 'Snap share', '%'],
  ['touch', 'Touches', ''],
  ['rec_tgt', 'Targets', ''],
  ['tgt_share', 'Target share', '%'],
  ['catch_pct', 'Catch rate', '%'],
  ['ypc', 'Yards per carry', ''],
  ['ypt', 'Yards per target', ''],
  ['rush_rz_att', 'Red-zone carries', ''],
  ['rec_rz_tgt', 'Red-zone targets', ''],
  ['rush_btkl', 'Broken tackles', ''],
  ['rush_yac', 'Yards after contact', ''],
  ['rec_drop', 'Drops', ''],
  ['anytime_tds', 'Total TDs', ''],
  ['ppg', 'Fantasy pts/game', ''],
]

export default function PlayerCard({ p, projKey, myTurn, busy, onDraft, onQueue, queued, onClose,
                                     onDrop, mine, waiverDays }) {
  useScrollLock()   // the page behind must not move while this is open
  const [tab, setTab] = useState('overview')
  const [imgFail, setImgFail] = useState(false)
  const [dragY, setDragY] = useState(0)
  const [confirmDrop, setConfirmDrop] = useState(false)
  const startY = React.useRef(null)

  // swipe the sheet down to dismiss
  const onTouchStart = e => { startY.current = e.touches[0].clientY }
  const onTouchMove = e => {
    if (startY.current == null) return
    const dy = e.touches[0].clientY - startY.current
    if (dy > 0) setDragY(dy)
  }
  const onTouchEnd = () => {
    if (dragY > 110) onClose()
    setDragY(0); startY.current = null
  }
  const proj = p.projd || {}
  const ly = p.lyd || {}
  const isDef = p.pos === 'DEF'
  const rows = SEASON_ROWS[p.pos] || []
  const hasSeason = rows.some(([k]) => proj[k] != null || ly[k] != null)
  const usage = USAGE.filter(([k]) => ly[k] != null)
  // a real 2025 line means games played, not just a stray rank left on the row
  const playedLastYear = (ly.gp || 0) > 0

  return (
    <div className="sheetback" onClick={() => !busy && onClose()}>
      <div className="sheet tall" onClick={e => e.stopPropagation()}
        style={dragY ? { transform: `translateY(${dragY}px)` } : undefined}>
        <div className="sheet-top">
          <div className="sheet-grab" onTouchStart={onTouchStart} onTouchMove={onTouchMove} onTouchEnd={onTouchEnd} />
          <button className="sheet-close" onClick={onClose} aria-label="Close">✕</button>
        </div>

        {/* ---- hero — faint team watermark behind, NFL-style ---- */}
        <div className="pc-hero">
          {teamLogo(p.team) && <img className="pc-water" src={teamLogo(p.team)} alt="" />}
          <div className="pc-shot">
            {imgFail || isDef
              ? <div className="pic" style={{width:66,height:66}}><span className={'ph pos-' + p.pos}>{p.pos}</span></div>
              : <img src={headshot(p.id)} alt="" onError={() => setImgFail(true)} />}
          </div>
          <div className="pc-id">
            <div className="pc-name">{p.name}</div>
            <div className="pc-sub">
              {teamLogo(p.team) && <img className="pc-logo" src={teamLogo(p.team)} alt="" />}
              <span className={'posbadge bg-' + p.pos}>{p.pos}</span>
              {p.team || 'FA'}{p.numj ? ` · #${p.numj}` : ''}
            </div>
            {p.inj && <div className="pc-inj">{p.inj}</div>}
          </div>
        </div>

        {/* ---- headline strip: labels above values, rank in the hexagon ---- */}
        <div className="pc-topstats">
          <div><b>{n(p.bye)}</b><span>BYE WK</span></div>
          <div><b>{n(p[projKey])}</b><span>2026 PROJ</span></div>
          <div className="pc-hex">
            <div className="hex">
              <div>
                <span>{p.pos} RNK</span>
                <b>{n(p.prank)}</b>
              </div>
            </div>
          </div>
          <div><b>{n(p.adp)}</b><span>ADP</span></div>
          <div><b>{n((p.lyd || {}).ppg)}</b><span>'25 PPG</span></div>
        </div>

        <div className="pc-tabs">
          <button className={tab === 'overview' ? 'on' : ''} onClick={() => setTab('overview')}>Overview</button>
          <button className={tab === 'stats' ? 'on' : ''} onClick={() => setTab('stats')}>Stats</button>
          <button className={tab === 'usage' ? 'on' : ''} onClick={() => setTab('usage')}>Usage</button>
          <button className={tab === 'bio' ? 'on' : ''} onClick={() => setTab('bio')}>Bio</button>
        </div>

        <div className="pc-body">
          {tab === 'overview' && (
            <>
              {hasSeason ? (
                <>
                  <div className="pc-h">Season stats</div>
                  <div className="statgrid">
                    <div className="sg-head">
                      <span />{rows.map(([k, lab]) => <span key={k}>{lab}</span>)}<span>FPTS</span>
                    </div>
                    <div className="sg-row">
                      <span className="sg-lab">PROJ 2026</span>
                      {rows.map(([k]) => <span key={k}>{n(proj[k])}</span>)}
                      <span className="sg-fpts">{n(p[projKey])}</span>
                    </div>
                    <div className="sg-row">
                      <span className="sg-lab">2025</span>
                      {rows.map(([k]) => <span key={k}>{n(ly[k])}</span>)}
                      <span className="sg-fpts">{n(ly.pts_ppr)}</span>
                    </div>
                  </div>
                </>
              ) : (
                <div className="hint pad">
                  {isDef ? 'Team defense — no individual stat line.' : 'No stat line available for this player.'}
                </div>
              )}

              {ly.pos_rank_ppr && (
                <div className="pc-callout">
                  Finished <strong>{p.pos}{ly.pos_rank_ppr}</strong> in 2025
                  {ly.ppg ? <> at <strong>{ly.ppg}</strong> points per game</> : null}
                  {ly.gp ? <> across <strong>{ly.gp}</strong> games</> : null}.
                </div>
              )}

              <div className="pc-h">2026 projection</div>
              {Object.keys(proj).length ? (
                <div className="kvgrid">
                  {proj.gp != null && <div><span>Games</span><b>{proj.gp}</b></div>}
                  {proj.touch != null && <div><span>Touches</span><b>{proj.touch}</b></div>}
                  {proj.rush_yd != null && <div><span>Rush yards</span><b>{proj.rush_yd}</b></div>}
                  {proj.rec_yd != null && <div><span>Rec yards</span><b>{proj.rec_yd}</b></div>}
                  {proj.pass_yd != null && <div><span>Pass yards</span><b>{proj.pass_yd}</b></div>}
                  {(proj.rush_td != null || proj.rec_td != null || proj.pass_td != null) &&
                    <div><span>Total TDs</span><b>{(proj.rush_td || 0) + (proj.rec_td || 0) + (proj.pass_td || 0)}</b></div>}
                </div>
              ) : <div className="hint pad">No projection published.</div>}
            </>
          )}

          {tab === 'stats' && (
            <>
              <Career p={p} projKey={projKey} />
              {/* A player who missed the season still carries a junk
                  position rank on the roster row (Tank Dell read "WR1249").
                  One stray number is worse than no block at all. */}
              {playedLastYear && <div className="pc-h">2025 full line</div>}
              {playedLastYear ? (
                <div className="kvgrid wide">
                  {[['gp', 'Games played'], ['gs', 'Games started'], ['pts_ppr', 'Fantasy points (PPR)'],
                    ['ppg', 'Points per game'], ['pos_rank_ppr', 'Position finish'],
                    ['pass_cmp', 'Completions'], ['pass_att', 'Attempts'], ['pass_yd', 'Passing yards'],
                    ['pass_td', 'Passing TDs'], ['pass_int', 'Interceptions'],
                    ['rush_att', 'Carries'], ['rush_yd', 'Rushing yards'], ['ypc', 'Yards per carry'],
                    ['rush_td', 'Rushing TDs'], ['rec', 'Receptions'], ['rec_tgt', 'Targets'],
                    ['rec_yd', 'Receiving yards'], ['ypr', 'Yards per catch'], ['rec_td', 'Receiving TDs'],
                    ['anytime_tds', 'Total touchdowns']]
                    .filter(([k]) => ly[k] != null)
                    .map(([k, lab]) => (
                      <div key={k}><span>{lab}</span><b>{k === 'pos_rank_ppr' ? `${p.pos}${ly[k]}` : ly[k]}</b></div>
                    ))}
                </div>
              ) : <div className="hint pad">No 2025 stat line — see the career table above for why.</div>}
            </>
          )}

          {tab === 'usage' && (
            <>
              <div className="pc-h">2025 usage &amp; efficiency</div>
              {usage.length ? (
                <>
                  {ly.snap_pct != null && (
                    <div className="barstat">
                      <div className="bs-top"><span>Snap share</span><b>{ly.snap_pct}%</b></div>
                      <div className="bs-track"><i style={{ width: Math.min(100, ly.snap_pct) + '%' }} /></div>
                      <div className="bs-note">{ly.off_snp} of {ly.tm_off_snp} team snaps</div>
                    </div>
                  )}
                  {ly.tgt_share != null && (
                    <div className="barstat">
                      <div className="bs-top"><span>Target share</span><b>{ly.tgt_share}%</b></div>
                      <div className="bs-track"><i style={{ width: Math.min(100, ly.tgt_share * 2) + '%' }} /></div>
                      <div className="bs-note">{ly.rec_tgt} targets</div>
                    </div>
                  )}
                  <div className="kvgrid wide">
                    {usage.filter(([k]) => k !== 'snap_pct' && k !== 'tgt_share').map(([k, lab, unit]) => (
                      <div key={k}><span>{lab}</span><b>{ly[k]}{unit}</b></div>
                    ))}
                  </div>
                </>
              ) : <div className="hint pad">No usage data for 2025.</div>}
              <Advanced p={p} />
              <p className="pc-source">
                Usage from Sleeper's 2025 feed; advanced metrics from nflverse — Pro Football
                Reference charting (broken tackles, yards before contact, drops, pressures) and
                NFL Next Gen Stats (separation, cushion, time to throw). Routes run is PFF's
                paid number and is not shown rather than approximated.
              </p>
            </>
          )}

          {tab === 'bio' && (
            <div className="kvgrid wide">
              {p.age != null && <div><span>Age</span><b>{p.age}</b></div>}
              {p.exp != null && <div><span>Experience</span><b>{p.exp === 0 ? 'Rookie' : `${p.exp} yrs`}</b></div>}
              {p.ht && <div><span>Height</span><b>{p.ht}</b></div>}
              {p.wt != null && <div><span>Weight</span><b>{p.wt} lb</b></div>}
              {p.numj != null && <div><span>Number</span><b>#{p.numj}</b></div>}
              {p.col && <div><span>College</span><b>{p.col}</b></div>}
              {p.dc != null && <div><span>Depth chart</span><b>{p.dc}</b></div>}
              {p.team && <div><span>Team</span><b>{p.team}</b></div>}
              {p.bye != null && <div><span>Bye week</span><b>{p.bye}</b></div>}
              {p.inj && <div><span>Status</span><b className="warn">{p.inj}</b></div>}
            </div>
          )}
        </div>

        {/* nothing to offer for someone else's player in the season —
            render no bar at all rather than an empty strip of space */}
        {(mine || onDrop === undefined) && <div className="pc-actions">
          {/* In the season the draft is over — the only thing you can do with
              your own player is drop him, and dropping is the one genuinely
              destructive tap in the app, so it confirms first. */}
          {mine ? (
            confirmDrop ? (
              <>
                <button className="btn secondary" disabled={busy}
                  onClick={() => setConfirmDrop(false)}>Keep him</button>
                <button className="btn big danger flex" disabled={busy} onClick={onDrop}>
                  {busy ? 'Dropping…' : `Yes, drop${waiverDays ? ` — ${waiverDays}d waivers` : ''}`}
                </button>
              </>
            ) : (
              <button className="btn big danger flex" onClick={() => setConfirmDrop(true)}>
                Drop {p.name.split(' ').slice(-1)[0]}
              </button>
            )
          ) : onDrop === undefined ? (
            <>
              <button className="btn secondary" onClick={onQueue}>{queued ? '★ Queued' : '☆ Queue'}</button>
              <button className="btn big good flex" disabled={!myTurn || busy} onClick={onDraft}>
                {busy ? 'Drafting…' : myTurn ? 'Draft him' : 'Not your turn'}
              </button>
            </>
          ) : null}
        </div>}
      </div>
    </div>
  )
}
